@Test
public void tempDirsAreStoredInPipelineConf() {
    DistributedPipeline distributedPipeline = Mockito.mock(DistributedPipeline.class, Mockito.CALLS_REAL_METHODS);
    Configuration testConfiguration = new Configuration();
    distributedPipeline.setConfiguration(testConfiguration);
    // no temp directory is present at startup
    Assert.assertEquals(null, distributedPipeline.getConfiguration().get("crunch.tmp.dirs"));
    // store a temp directory
    distributedPipeline.storeTempDirLocation(new Path(testTempDirPath1));
    Assert.assertEquals(testTempDirPath1.toString(), distributedPipeline.getConfiguration().get("crunch.tmp.dirs"));
    // store one more temp directory
    distributedPipeline.storeTempDirLocation(new Path(testTempDirPath2));
    Assert.assertEquals(String.format("%s:%s", testTempDirPath1.toString(), testTempDirPath2.toString()), distributedPipeline.getConfiguration().get("crunch.tmp.dirs"));
    // try to store the first temp directory again, not added again
    distributedPipeline.storeTempDirLocation(new Path(testTempDirPath1));
    Assert.assertEquals(String.format("%s:%s", testTempDirPath1.toString(), testTempDirPath2.toString()), distributedPipeline.getConfiguration().get("crunch.tmp.dirs"));
}

@Test
public void counterTest() throws Exception {
    Pipeline pipeline = MemPipeline.getInstance();
    // Single row PCollection.
    PCollection<String> objects = MemPipeline.collectionOf(Arrays.asList(new String[] { "hello world" }));
    System.out.println("Objects: " + ((MemCollection) objects).getCollection());
    // Counter creating Map.
    PCollection<String> objects2 = objects.parallelDo("Create counters", new MapFn<String, String>() {

        @Override
        public String map(String input) {
            for (int i = 0; i < 200; ++i) {
                this.increment("testCounter", String.valueOf(i));
            }
            return input;
        }
    }, Writables.strings());
    // Run it!
    pipeline.done();
    System.out.println("Objects2: " + ((MemCollection) objects2).getCollection());
}

/**
 * Specific test for the situation outlined in CRUNCH-607, which was that deriving two PCollections from the same
 * PGroupedTable would throw an IllegalStateException from SingleUseIterable. This just ensures that this case
 * doesn't return.
 */
@Test
public void testGroupedCollectionReuse() {
    PCollection<String> stringValues = MemPipeline.typedCollectionOf(Avros.strings(), "one", "two", "three");
    PGroupedTable<String, String> groupedTable = stringValues.by(IdentityFn.<String>getInstance(), Avros.strings()).groupByKey();
    // Here we re-use the grouped table twice, meaning its internal iterators will need to be iterated multiple times
    PTable<String, Integer> stringLengthTable = groupedTable.mapValues(new MaxStringLengthFn(), Avros.ints());
    // Previous to LP-607, this would fail with an IllegalStateException from SingleUseIterable
    Set<String> keys = ImmutableSet.copyOf(groupedTable.ungroup().join(stringLengthTable).keys().materialize());
