}

@Test
public void testCompare() throws IOException {
    doTestCompare(new TupleWritable(new Writable[] { new IntWritable(1) }), new TupleWritable(new Writable[] { new IntWritable(2) }), -1);
    doTestCompare(new TupleWritable(new Writable[] { new IntWritable(1) }), new TupleWritable(new Writable[] { new IntWritable(1) }), 0);
    doTestCompare(new TupleWritable(new Writable[] { new IntWritable(1), new IntWritable(1) }), new TupleWritable(new Writable[] { new IntWritable(1), new IntWritable(2) }), -1);
    doTestCompare(new TupleWritable(new Writable[] { new IntWritable(1), new IntWritable(2) }), new TupleWritable(new Writable[] { new IntWritable(1), new IntWritable(2) }), 0);
    doTestCompare(new TupleWritable(new Writable[] { null }), new TupleWritable(new Writable[] { new IntWritable(1) }), -1);
    doTestCompare(new TupleWritable(new Writable[] { new IntWritable(1) }), new TupleWritable(new Writable[] { new Text("1") }), // code for IntWritable is larger than code for Text
    1);
    doTestCompare(new TupleWritable(new Writable[] { new IntWritable(1) }), new TupleWritable(new Writable[] { new IntWritable(1), new IntWritable(2) }), // shorter is less
    -1);
}

