@Test
public void mapFns() throws IOException {
    ConsumerRecord<BytesWritable, BytesWritable> record = new ConsumerRecord<>("topic", 1, 2, 3L, TimestampType.CREATE_TIME, 4L, 5, 6, new BytesWritable("key".getBytes()), new BytesWritable("value".getBytes()));
    PCollection<BytesWritable> bytes = MemPipeline.collectionOf(new BytesWritable(ConsumerRecordHelper.serialize(record)));
    PCollection<ConsumerRecord<BytesWritable, BytesWritable>> records = bytes.parallelDo(new ConsumerRecordHelper.BytesToConsumerRecord(), ConsumerRecordHelper.CONSUMER_RECORD_P_TYPE);
    PCollection<BytesWritable> newBytes = records.parallelDo(new ConsumerRecordHelper.ConsumerRecordToBytes(), Writables.writables(BytesWritable.class));
    ConsumerRecord<BytesWritable, BytesWritable> newRecord = ConsumerRecordHelper.deserialize(newBytes.materialize().iterator().next().getBytes());
    assertRecordsAreEqual(record, newRecord);
}

