@Test
public void iterateSkipInitialValues() {
    consumer = new KafkaConsumer<>(consumerProps, new ClusterTest.StringSerDe(), new ClusterTest.StringSerDe());
    int loops = 10;
    int numPerLoop = 100;
    List<String> keys = writeData(props, topic, "batch1", loops, numPerLoop);
