    thenReturn(null);
    Iterable<ConsumerRecord<String, String>> data = new KafkaRecordsIterable<>(mockedConsumer, offsets, new Properties());
    int count = 0;
    for (ConsumerRecord<String, String> record : data) {
        count++;
    }
