@Test
public void smallCollectionsShouldNotHaveNullLength() throws Exception {
    Pipeline p = new SparkPipeline("local", "foobar");
    final ImmutableList<String> allFruits = ImmutableList.of("apelsin", "banan", "citron", "daddel");
    final ArrayList<ImmutableList<String>> fruitLists = new ArrayList<>();
    for (int i = 0; i <= allFruits.size(); ++i) {
        fruitLists.add(ImmutableList.copyOf(allFruits.subList(0, i)));
    }
    final ArrayList<PObject<Long>> results = new ArrayList<>();
    for (ImmutableList<String> fruit : fruitLists) {
        final PCollection<String> collection = p.create(fruit, Avros.strings());
        results.add(collection.length());
    }
    p.run();
    final Iterable<Long> lengths = Iterables.transform(results, new Function<PObject<Long>, Long>() {

        @Nullable
        @Override
        public Long apply(@Nullable PObject<Long> input) {
            return input.getValue();
        }
    });
    for (Long length : lengths) {
        assertThat(length, not(nullValue()));
    }
    p.done();
}

@Test
public void fieldsWithIgnoredSortOrderAreNotUsedInEquals() throws Exception {
    Schema mySchema = Schema.createRecord("foo", "", "", false);
    mySchema.setFields(Lists.newArrayList(new Field("field1", Schema.create(Type.STRING), null, JsonNodeFactory.instance.textNode(""), Order.ASCENDING), new Field("field2", Schema.create(Type.STRING), null, JsonNodeFactory.instance.textNode(""), Order.IGNORE)));
    GenericRecordBuilder myGRB = new GenericRecordBuilder(mySchema);
    Record myRecord1 = myGRB.set("field1", "hello").set("field2", "world").build();
    Record myRecord2 = myGRB.set("field1", "hello").set("field2", "there").build();
    assertEquals(myRecord1, myRecord2);
    AvroSerDe serde = new AvroSerDe(Avros.generics(mySchema), null);
    assertEquals(serde.toBytes(myRecord1), serde.toBytes(myRecord2));
}

